input.command:
cd "~/Downloads" && for f in *; do [ -f "$f" ] || continue
lc=$(echo "$f" | tr 'A-Z' 'a-z')
case "$lc" in
  '~$'*|*.tmp|*.crdownload|*.part|*.download) echo "{\"op\":\"trash\",\"path\":\"$f\"},"; continue;;
  img_*|pxl_*) d=Photos;;
  screenshot*) d=Screenshots;;
  *.png|*.jpg|*.webp|*.gif|*.svg|*.tiff|*.heic) d=Images;;
  *.mp4|*.mov|*.mkv) d=Videos;;
  *.mp3|*.flac|*.m4a|*.m4r) d=Audio;;
  *.pdf|*.docx|*.txt|*.md) d=Documents;;
  *.xlsx|*.csv) d=Spreadsheets;;
  *.pptx|*.key) d=Presentations;;
  *.zip|*.7z|*.tar.gz) d=Archives;;
  *.exe|*.msi|*.dmg) d=Installers;;
  *.py|*.html|*.css|*.json) d=Code;;
  *) d=Other;;
esac
[ "$f" = ".mcp.json" ] && continue
echo "{\"op\":\"move\",\"from\":\"$f\",\"to\":\"$d/$f\"},"
done > /tmp/ops.txt; wc -l /tmp/ops.txt; grep -c trash /tmp/ops.txt; grep -v trash /tmp/ops.txt | sed 's/.*"to":"\([^/]*\)\/.*/\1/' | sort | uniq -c; grep -E 'Other|trash' /tmp/ops.txt

